import { basename } from 'node:path';

import { convertBits } from './lib/bech32/convert-bits.mjs';
import { parseArguments } from './lib/cli/parse-args.mjs';
import { formatPythonValue } from './lib/format/python-repr.mjs';
import { parseCommaSeparatedIntegers } from './lib/number/python-int.mjs';

function main() {
  const programName = basename(process.argv[1] ?? 'test14.mjs');
  const parseResult = parseArguments(process.argv.slice(2), programName);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.text);
    process.exit(0);
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.text);
    process.exit(parseResult.code);
