  const step1 = convertBits(data, parseResult.values.b, parseResult.values.c);
  const step2 = convertBits(step1, parseResult.values.c, parseResult.values.d);

  process.stdout.write(`${formatPythonValue(step1)}\n${formatPythonValue(step2)}\n`);
}

main();

